  @override
  String get step4ZamzamText =>
      '\nپانی پئیں اور اپنے سر پر بھی ڈالیں۔\n\nجابر رضی اللہ عنہ سے روایت ہے: «نبی ﷺ زمزم کے کنویں پر تشریف لائے، اس سے پانی پیا اور اپنے سر پر ڈالا۔» یہ حدیث صحیح ہے، اسے احمد (3/394) اور ابن خزیمہ (4/305) نے روایت کیا ہے۔ اس حدیث کی صحت کی تصدیق زرکشی، بدر الدین عینی اور شعیب الارنؤوط نے کی ہے۔ دیکھیں «عمدۃ القاری» (9/227)، «حاشیہ علی المناسک» (ص 263)، «تخریج المسند» (15243)۔\n\nجابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «زمزم کا پانی اسی مقصد کے لیے ہے جس کے لیے اسے پیا جائے۔» یہ حدیث احمد (3/357)، ابن ماجہ (3062) اور الحاکم (1739) نے روایت کی ہے۔ اس حدیث کی صحت کی تصدیق سفیان بن عیینہ، منذری، دمیاطی، ابن القیم، زرکشی، ابن حجر اور البانی جیسے علماء نے کی ہے۔ دیکھیں «المجالسہ» (509)، «المتجر الرابح» (982)، «زاد المعاد» (4/393)، «المقاصد الحسنہ» (928)، «فیض القدیر» (7759) اور «صحیح الترغیب» (1165)۔\n\nامام شوکانی نے فرمایا: «اس حدیث میں دلیل ہے کہ زمزم کا پانی پینے والے کے لیے مفید ہے، خواہ اس کی نیت کچھ بھی ہو، دنیا کے کسی کام کے لیے یا آخرت کے لیے۔ ‹یہ اسی مقصد کے لیے ہے جس کے لیے پیا جائے› کے الفاظ عام ہیں۔» دیکھیں «نیل الاوطار» (5/105)۔\nامام نووی نے فرمایا: «اس حدیث کا مطلب یہ ہے کہ جو شخص کسی خاص مقصد کے لیے یہ پانی پیے گا، وہ اسے حاصل کر لے گا۔ علماء اور نیک لوگوں نے دنیا اور آخرت کی اپنی ضرورتوں کے لیے اسے آزمایا اور اللہ تعالیٰ کے فضل سے انہیں وہ حاصل ہوا۔» دیکھیں «تہذیب الاسماء واللغات» (3/139)۔';

