  @override
  String get etiquetteMannersText5 =>
      'حج اور عمرہ کرنے والے کو اچھے اخلاق سے آراستہ ہونا چاہیے اور لوگوں کے ساتھ بہترین سلوک کرنا چاہیے۔\n\nابوذر رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: «جہاں کہیں بھی ہو اللہ سے ڈرو! برائی کے بعد نیکی کرو جو اسے مٹا دے، اور لوگوں کے ساتھ اچھے اخلاق سے پیش آؤ۔» ترمذی، 1987۔\n\nعبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ نبی ﷺ نے فرمایا: «جو شخص چاہتا ہے کہ اسے آگ سے دور کر کے جنت میں داخل کیا جائے، تو اس کی موت اس حال میں آئے کہ وہ اللہ اور آخرت کے دن پر ایمان رکھتا ہو، اور لوگوں کے ساتھ ویسا ہی سلوک کرے جیسا وہ چاہتا ہے کہ لوگ اس کے ساتھ کریں۔» مسلم، 1844۔';

  @override
  String get etiquetteMannersText6 =>
      'حج اور عمرہ کرنے والے کو اللہ کے ذکر، دعا اور استغفار میں مشغول رہنا چاہیے۔ اسے اپنی زبان کو اچھی بات کے سوا ہر چیز سے بچانا چاہیے، اور اپنا سارا وقت ان کاموں میں لگانا چاہیے جو دنیا اور آخرت دونوں میں اس کے لیے مفید ہوں۔\n\nابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہے وہ اچھی بات کہے یا خاموش رہے۔» بخاری، 6018؛ مسلم، 47۔\n\nابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «دو نعمتیں ایسی ہیں جن کے بارے میں بہت سے لوگ دھوکے میں ہیں: صحت اور فراغت۔» بخاری، 6412۔';

  @override
  String get etiquetteMannersText7 =>
      'حج اور عمرہ کرنے والے کو اپنی بات یا عمل سے دوسروں کو تکلیف دینے سے بچنا چاہیے۔\n\nنبی ﷺ نے فرمایا: «مسلمان وہ ہے جس کی زبان اور ہاتھ سے (دوسرے) مسلمان محفوظ رہیں۔» بخاری، 10؛ مسلم، 41۔\n\nاگر کوئی مسلمان خود سگریٹ پیتا ہے تو اسے سگریٹ کے دھوئیں کی بدبو سے دوسرے مسلمانوں کو تکلیف دینے سے بھی بچنا چاہیے۔ حالانکہ اس پر پہلے ہی لازم ہے کہ وہ سگریٹ نوشی چھوڑ دے اور اللہ سے توبہ کرے، کیونکہ سگریٹ نوشی صحت کو نقصان پہنچاتی ہے اور مال کو برباد کرتی ہے۔\n\nمسلمان کو ہمیشہ اور ہر جگہ ان اچھے اخلاق کو اپنانے کی کوشش کرنی چاہیے، خاص طور پر حج یا عمرہ کے سفر کے دوران۔';

  @override
  String get hajjUmrahVirtuesText1 =>
      'حج اور عمرہ کی فضیلت کے بارے میں رسول اللہ ﷺ سے صحیح احادیث مروی ہیں۔ ان میں سے چند یہ ہیں:\n\nابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «ایک عمرہ دوسرے عمرے تک ان گناہوں کا کفارہ ہے جو ان کے درمیان ہوئے، اور حجِ مبرور کا بدلہ جنت کے سوا کچھ نہیں۔» بخاری، 1773؛ مسلم، 1349۔\n\nابن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «حج اور عمرہ پے در پے کیا کرو، کیونکہ یہ دونوں فقر اور گناہوں کو اس طرح دور کر دیتے ہیں جیسے بھٹی لوہے، سونے اور چاندی کے میل کو دور کر دیتی ہے۔ اور حجِ مبرور کا بدلہ جنت کے سوا کچھ نہیں۔» ترمذی، 810؛ نسائی، 2631۔\n\nابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «حج اور عمرہ پے در پے کیا کرو، کیونکہ یہ دونوں فقر اور گناہوں کو اس طرح دور کر دیتے ہیں جیسے بھٹی لوہے کے میل کو دور کر دیتی ہے۔» نسائی، 2630۔';

  @override
  String get hajjUmrahVirtuesText2 =>
      'ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے عرض کیا: «اے اللہ کے رسول! ہم جہاد کو سب سے افضل عمل سمجھتے ہیں، تو کیا ہم جہاد نہ کریں؟» نبی ﷺ نے فرمایا: «نہیں! تمہارے (عورتوں کے) لیے سب سے افضل جہاد حجِ مبرور ہے۔» بخاری، 1520۔\n\nایک اور روایت میں ہے کہ عائشہ رضی اللہ عنہا نے عرض کیا: «اے اللہ کے رسول! کیا عورتوں پر جہاد ہے؟» نبی ﷺ نے فرمایا: «ان پر ایسا جہاد ہے جس میں لڑائی نہیں، اور وہ حج اور عمرہ ہے۔» ابن ماجہ، 2901۔';

  @override
  String get hajjUmrahVirtuesText3 =>
      'ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: «جس نے اللہ کے لیے حج کیا اور اس میں نہ بیوی سے قربت کی اور نہ کوئی گناہ اور نازیبا کام کیا، وہ اس دن کی طرح (گناہوں سے پاک ہو کر) لوٹتا ہے جس دن اس کی ماں نے اسے جنا تھا۔» بخاری، 1521؛ مسلم، 1350۔\n\nیہ بھی روایت ہے کہ نبی ﷺ نے عمرو بن العاص رضی اللہ عنہ سے فرمایا: «کیا تم نہیں جانتے کہ اسلام پہلے کے تمام گناہوں کو مٹا دیتا ہے، ہجرت پہلے کے تمام گناہوں کو مٹا دیتی ہے اور حج پہلے کے تمام گناہوں کو مٹا دیتا ہے؟» مسلم، 121۔\n\nحجِ مبرور (جس کا ذکر اوپر کی احادیث میں ہے) وہ حج ہے جو رسول اللہ ﷺ کی سنت کے مطابق ہو۔';

  @override
  String get hajjUmrahVirtuesText4 =>
      'جابر رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: «مجھ سے اپنے حج کے مناسک سیکھ لو، کیونکہ میں نہیں جانتا، شاید اس حج کے بعد میں دوبارہ حج نہ کر سکوں۔» مسلم، 1297۔\n\nاس حدیث کی ایک اور روایت میں ہے کہ نبی ﷺ نے فرمایا: «اے لوگو! مجھ سے اپنے مناسک سیکھ لو، کیونکہ میں نہیں جانتا، شاید اس سال کے بعد میں حج نہ کر سکوں۔» نسائی، 3062۔';

  @override
  String get hajjUmrahObligationObligationEvidence =>
      'حج اور عمرہ زندگی میں ایک مرتبہ فرض ہیں، اور جو انہیں ایک سے زیادہ مرتبہ ادا کرے تو وہ نفلی عبادت شمار ہوگی۔\n\nنذر ماننے سے بھی حج اور عمرہ واجب ہو جاتے ہیں۔ اگر کسی نے اللہ کے لیے حج یا عمرہ کی نذر مانی ہو تو اس نذر کو پورا کرنا واجب ہے۔\n\nاگر کسی نے نفلی حج یا عمرہ شروع کر دیا ہو تو اسے مکمل کرنا لازم ہے، کیونکہ اللہ تعالیٰ نے فرمایا: «اور اللہ کے لیے حج اور عمرہ پورا کرو۔» (سورۃ البقرہ، آیت 196)\n\nحج کی فرضیت قرآن، سنت اور مسلمانوں کے اجماع سے ثابت ہے۔\nاللہ تعالیٰ نے فرمایا: «اور لوگوں پر اللہ کا حق ہے کہ جو اس گھر تک پہنچنے کی استطاعت رکھتا ہو وہ اس کا حج کرے۔ اور جو انکار کرے تو بے شک اللہ تمام جہانوں سے بے نیاز ہے۔» (سورۃ آلِ عمران، آیت 97)\n\nنبی ﷺ نے فرمایا: «اسلام کی بنیاد پانچ چیزوں پر ہے: اس بات کی گواہی دینا کہ اللہ کے سوا کوئی سچا معبود نہیں اور محمد اللہ کے رسول ہیں، نماز قائم کرنا، زکوٰۃ ادا کرنا، حج کرنا اور رمضان کے روزے رکھنا۔» بخاری، 8؛ مسلم، 16۔\nاور یہ بھی: «اسلام یہ ہے کہ تم گواہی دو کہ اللہ کے سوا کوئی سچا معبود نہیں اور محمد اللہ کے رسول ہیں، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو اور اگر استطاعت ہو تو بیت اللہ کا حج کرو۔» مسلم، 8۔\n\nابوہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: «ایک مرتبہ رسول اللہ ﷺ نے ہمیں خطبہ دیا اور فرمایا: ‹اے لوگو! تم پر حج فرض کیا گیا ہے، لہٰذا حج کرو۔› ایک شخص نے پوچھا: ‹کیا ہر سال، اے اللہ کے رسول؟› نبی ﷺ خاموش رہے یہاں تک کہ اس نے تین مرتبہ یہ سوال دہرایا۔ پھر رسول اللہ ﷺ نے فرمایا: ‹اگر میں ہاں کہہ دیتا تو یقیناً یہ تم پر فرض ہو جاتا، اور تم اسے ادا نہ کر پاتے۔›» مسلم، 1337۔\n\nاور مسلمانوں کا اس پر اجماع ہے کہ جس شخص میں حج کی فرضیت کی تمام شرائط جمع ہوں اس پر حج فرض ہے۔';

  @override
  String get hajjUmrahObligationEvidenceUmrahObligation =>
      'جہاں تک عمرہ کا تعلق ہے تو درج ذیل احادیث اس کی فرضیت پر دلالت کرتی ہیں:\n\n1 - عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے پوچھا: «اے اللہ کے رسول! کیا عورتوں پر جہاد ہے؟» رسول اللہ ﷺ نے فرمایا: «ہاں، ان پر ایسا جہاد ہے جس میں لڑائی نہیں، اور وہ حج اور عمرہ ہے۔» احمد، 6/165؛ ابن ماجہ، 2901۔\nیہ حدیث ذکر کرنے کے بعد امام ابن خزیمہ رحمہ اللہ نے فرمایا: «نبی ﷺ کے الفاظ ‹ان پر ایسا جہاد ہے جس میں لڑائی نہیں، اور وہ حج اور عمرہ ہے› میں یہ وضاحت ہے کہ عمرہ بھی حج کی طرح فرض ہے۔» دیکھیں «صحیح ابن خزیمہ»، حدیث نمبر 3074۔\n\n2 - عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «اسلام یہ ہے کہ تم گواہی دو کہ اللہ کے سوا کوئی سچا معبود نہیں اور محمد اللہ کے رسول ہیں، نماز قائم کرو، زکوٰۃ ادا کرو، حج اور عمرہ کرو، جنابت سے غسل کرو، اچھی طرح وضو کرو اور رمضان کے مہینے کے روزے رکھو۔» دیکھیں «صحیح ابن خزیمہ»، حدیث نمبر 3065۔ یہ حدیث دارقطنی، 2/282 میں بھی ہے۔\n\n3 - ابو رزین عقیلی رضی اللہ عنہ سے روایت ہے کہ وہ نبی ﷺ کے پاس آئے اور عرض کیا: «اے اللہ کے رسول! میرے والد بہت بوڑھے ہیں، نہ حج کر سکتے ہیں نہ عمرہ، اور نہ سواری پر بیٹھ سکتے ہیں۔» نبی ﷺ نے فرمایا: «اپنے والد کی طرف سے حج اور عمرہ کرو۔» ترمذی، 930۔\n\n4 - صبی بن معبد سے روایت ہے کہ انہوں نے عمر بن خطاب رضی اللہ عنہ سے کہا: «اے امیر المؤمنین! میں ایک بدو اور عیسائی تھا، پھر میں نے اسلام قبول کیا۔ میں جہاد کا شوق رکھتا ہوں، لیکن میں نے دیکھا کہ مجھ پر حج اور عمرہ فرض ہیں۔ میں نے اپنی قوم کے ایک شخص سے اس بارے میں پوچھا تو اس نے کہا: ‹حج اور عمرہ ایک ساتھ کرو اور جو جانور میسر ہو اس کی قربانی کرو›، چنانچہ میں نے دونوں کو ایک ساتھ ادا کیا۔» تو عمر رضی اللہ عنہ نے فرمایا: «تمہیں اپنے نبی ﷺ کی سنت کی ہدایت ملی۔» ابو داؤد، 1799۔';

