  @override
  String get safarSunnahsContent =>
      'سفر پر روانگی سے متعلق چند سنتیں:\n\n1) سفر پر روانہ ہونے سے پہلے اللہ سے دعا\nابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ جب سفر پر روانہ ہونے کے لیے اپنے اونٹ پر سوار ہوتے تو تین مرتبہ «اللہ اکبر» کہتے، پھر یہ فرماتے: «پاک ہے وہ ذات جس نے اسے ہمارے تابع کر دیا، ورنہ ہم اسے قابو میں نہ لا سکتے تھے۔ اور بے شک ہم اپنے رب کی طرف لوٹنے والے ہیں۔ اے اللہ! ہم اپنے اس سفر میں تجھ سے نیکی اور تقویٰ مانگتے ہیں، اور ایسے عمل جو تجھے پسند ہوں۔ اے اللہ! ہمارا یہ سفر ہم پر آسان کر دے اور اس کی دوری ہمارے لیے لپیٹ دے۔ اے اللہ! تو ہی سفر میں ساتھی ہے اور گھر والوں میں نگہبان ہے۔ اے اللہ! میں تیری پناہ مانگتا ہوں سفر کی مشقت سے، ناخوشگوار منظر سے، اور مال اور اہل و عیال میں بری واپسی سے!»\nسُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ\n\nاللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنْ الْعَمَلِ مَا تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلِبِ فِي الْمَالِ وَالْأَهْلِ\n\nواپسی پر آپ ﷺ یہی کلمات دہراتے اور یہ اضافہ فرماتے:\nآيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ\n\n«ہم لوٹنے والے ہیں، توبہ کرنے والے ہیں، عبادت کرنے والے ہیں اور اپنے رب کی حمد کرنے والے ہیں۔» (صحیح مسلم، 1342)\n\nعلی بن ربیعہ سے روایت ہے کہ انہوں نے کہا: «میں نے دیکھا کہ علی بن ابی طالب رضی اللہ عنہ کے پاس سواری لائی گئی تاکہ وہ اس پر سوار ہوں۔ جب انہوں نے رکاب میں پاؤں رکھا تو کہا:\nبِسْمِ اللَّهِ\n\n«اللہ کے نام سے»، اور جب اس پر سیدھے بیٹھ گئے تو کہا:\nسُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ\n«پاک ہے وہ ذات جس نے اسے ہمارے تابع کر دیا، ورنہ ہم اسے قابو میں نہ لا سکتے تھے، اور بے شک ہم اپنے رب کی طرف لوٹنے والے ہیں۔» پھر تین مرتبہ «تمام تعریفیں اللہ کے لیے ہیں» (الْحَمْدُ لِلَّهِ) اور «اللہ سب سے بڑا ہے» (الله أكبر) کہا، پھر یہ کہا:\n«تو پاک ہے! بے شک میں نے اپنے اوپر ظلم کیا، پس مجھے بخش دے، کیونکہ تیرے سوا کوئی گناہوں کو نہیں بخشتا!»\nسُبْحَانَكَ إِنِّي قَدْ ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ\n\n— پھر وہ مسکرا دیے۔ ان سے پوچھا گیا: «اے امیر المؤمنین! آپ کیوں مسکرائے؟» انہوں نے کہا: «میں نے نبی ﷺ کو دیکھا کہ آپ نے بالکل ویسا ہی کیا جیسا میں نے ابھی کیا، پھر آپ مسکرائے۔ میں نے پوچھا: ‹اے اللہ کے رسول! آپ کیوں مسکرائے؟› آپ ﷺ نے فرمایا: ‹بے شک تمہارا رب اس وقت خوش ہوتا ہے جب اس کا بندہ کہتا ہے:\nرَبِّ اغْفِرْ لِي ذُنُوبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ غَيْرُك\n\n«اے میرے رب! میرے گناہ بخش دے، کیونکہ تیرے سوا کوئی گناہوں کو نہیں بخشتا!»\n— اور اللہ فرماتا ہے: «میرا بندہ جانتا ہے کہ میرے سوا کوئی گناہوں کو نہیں بخشتا»›۔» (سنن ترمذی، 3446؛ شیخ البانی نے اسے صحیح قرار دیا)\n\n2) جمعرات کے دن سفر پر روانہ ہونا؛ رات کو سفر کرنا\nکعب بن مالک رضی اللہ عنہ سے روایت ہے کہ «نبی ﷺ جمعرات کے دن تبوک کے لیے روانہ ہوئے، اور آپ عام طور پر جمعرات کو سفر پر نکلنا پسند فرماتے تھے۔» (صحیح بخاری، 2949)\nانس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «رات کے وقت سفر کیا کرو، کیونکہ رات کو زمین لپیٹ دی جاتی ہے۔» (صحیح الجامع، 4064)\n\n3) ساتھی تلاش کرنا اور ان میں سے ایک کو امیر بنانا جس کی اطاعت کی جائے\nابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «اگر لوگ اکیلے سفر کرنے کے بارے میں وہ جان لیں جو میں جانتا ہوں تو کوئی سوار رات کو اکیلا سفر نہ کرے۔» (بخاری، 2998)\nابو سعید اور ابوہریرہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «جب تین آدمی سفر پر نکلیں تو اپنے میں سے ایک کو امیر بنا لیں۔» (صحیح الجامع، 500)\n\n4) بلندی پر چڑھتے وقت اللہ کی بڑائی بیان کرنا اور نشیب میں اترتے وقت اس کی پاکی بیان کرنا\nجابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ انہوں نے کہا: «جب ہم اوپر چڑھتے تو «اللہ اکبر» کہتے، اور جب نیچے اترتے تو «سبحان اللہ» کہتے۔» (صحیح بخاری، 2993)\n\n5) نمازوں کو جمع اور قصر کرنا\nانس رضی اللہ عنہ سے روایت ہے: «رسول اللہ ﷺ سفر میں مغرب اور عشاء کی نمازیں جمع کر کے پڑھتے تھے۔» (صحیح بخاری، 1108)\nانس رضی اللہ عنہ سے روایت ہے: «ہم نبی ﷺ کے ساتھ مدینہ سے مکہ کی طرف نکلے، اور آپ مدینہ واپس آنے تک دو دو رکعت پڑھتے رہے۔» (صحیح بخاری، 1081)\n\n6) وتر، چاشت اور فجر سے پہلے کی دو رکعتوں کے سوا نفل نمازیں چھوڑ دینا\nابو قتادہ رضی اللہ عنہ سے روایت ہے کہ «رسول اللہ ﷺ سفر میں فجر کی فرض نماز سے پہلے دو رکعت پڑھتے تھے۔» (مسلم، 680)\nام ہانی رضی اللہ عنہا سے روایت ہے کہ «فتحِ مکہ کے دن نبی ﷺ نے چاشت کی 8 رکعتیں پڑھیں۔» اس وقت آپ سفر میں تھے۔ (بخاری، 357؛ مسلم، 336)\nابن عمر رضی اللہ عنہما سے روایت ہے کہ «نبی ﷺ سفر میں اپنی سواری پر بیٹھے ہوئے وتر پڑھتے تھے۔» (بخاری، 1000)\n\n7) سواری یا گاڑی پر بیٹھے ہوئے نفل نماز پڑھنا\nابن عمر رضی اللہ عنہما سے روایت ہے کہ «نبی ﷺ سفر میں اپنی سواری پر بیٹھے ہوئے وتر پڑھتے تھے۔» (بخاری، 1000)\n\n8) سفر میں کثرت سے دعا کرنا\nرسول اللہ ﷺ نے فرمایا: «تین دعائیں قبول ہوتی ہیں: مظلوم کی دعا، مسافر کی دعا، اور والد کی اپنی اولاد کے خلاف دعا۔» (بخاری، 481)\n\n9) راستے سے مسافروں کو تکلیف دینے والی چیز ہٹانا\nابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «ایمان کی ستر (یا ساٹھ) سے زیادہ شاخیں ہیں، جن میں سب سے افضل ‹لا الٰہ الا اللہ› کہنا ہے، اور سب سے ادنیٰ راستے سے تکلیف دہ چیز ہٹانا ہے۔ اور حیا بھی ایمان کی ایک شاخ ہے۔» (مختصر صحیح مسلم، 31)\n\n10) کسی جگہ پڑاؤ ڈالتے وقت کی دعا\nخولہ بنت حکیم رضی اللہ عنہا سے روایت ہے کہ انہوں نے کہا: «میں نے رسول اللہ ﷺ کو فرماتے سنا: ‹جو شخص کسی جگہ اترے اور یہ کہے:\n«میں اللہ کے کامل کلمات کی پناہ مانگتا ہوں اس کی مخلوق کے شر سے!»\nأَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ\n— تو اسے کوئی چیز نقصان نہیں پہنچائے گی یہاں تک کہ وہ اس جگہ سے روانہ ہو جائے۔›» (مسلم، 2708)\n\n11) سفر کا مقصد پورا ہونے کے بعد جلد واپس آنا\nابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: «سفر عذاب کا ایک ٹکڑا ہے، جو تم میں سے کسی کو اس کے کھانے، پینے اور سونے سے روک دیتا ہے؛ لہٰذا جب تم میں سے کوئی اپنے سفر کا مقصد پورا کر لے تو جلد اپنے گھر والوں کے پاس لوٹ آئے۔» (بخاری، 1804؛ مسلم، 1927)\n\n12) دن کے وقت گھر والوں کے پاس واپس آنا\nانس رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: «رسول اللہ ﷺ رات کو اپنے گھر والوں کے پاس نہیں آتے تھے؛ آپ عام طور پر صبح یا شام کو آتے تھے۔» (بخاری، 1800؛ مسلم، 1928)\n\n13) سفر سے واپسی پر دو رکعت نماز پڑھنا\nکعب بن مالک رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: «جب رسول اللہ ﷺ سفر سے (مدینہ) واپس آتے تو پہلے مسجد جاتے اور دو رکعت نماز پڑھتے، پھر کچھ دیر وہاں لوگوں کے ساتھ بیٹھتے۔» (صحیح بخاری، 4418)\n';

